def think(thought, **_extra):
    import json, os, datetime, hashlib, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0479000" if __import__("os").path.isdir("./environment_mix/0479000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Resolve current session context (ambient): choose an active session if present.
    sessions = _load("sessions.json")
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str) and s.get("id"):
            sess = s
            break

    if not sess:
        # No session context available
        return _err("UNAUTHORIZED", "No active session context is available.")

    session_id = sess["id"]

    # Load other collections
    thoughts = _load("thoughts.json")
    counters = _load("session_counters.json")
    events = _load("session_events.json")

    # Ensure session exists (FK integrity)
    if not any(isinstance(s, dict) and s.get("id") == session_id for s in sessions):
        return _err("NOT_FOUND", "Session does not exist.", session_id=session_id)

    # Enforce session lifecycle
    if sess.get("status") == "closed":
        return _err("INVALID_TRANSITION", "Session is closed; cannot append thoughts.", session_id=session_id)

    # Validate input
    if not isinstance(thought, str):
        return _err("VALIDATION_ERROR", "`thought` must be a string.")
    if thought.strip() == "":
        return _err("VALIDATION_ERROR", "`thought` must be a non-empty string.")
    if len(thought) > 20000:
        return _err("VALIDATION_ERROR", "`thought` exceeds maximum length of 20000 characters.", max_length=20000)

    # Find or create counters row for session
    ctr = None
    for c in counters:
        if isinstance(c, dict) and c.get("session_id") == session_id:
            ctr = c
            break
    if ctr is None:
        ctr = {
            "session_id": session_id,
            "total_thoughts": 0,
            "total_chars": 0,
            "max_seq": 0,
            "first_thought_at": None,
            "last_thought_at": None,
            "last_cleared_at": None,
            "created_at": now,
            "updated_at": now,
        }
        counters.append(ctr)

    # Allocate seq (monotonic) and insert in a single "transaction" (in-memory then persist)
    next_seq = int(ctr.get("max_seq") or 0) + 1

    # Enforce unique(session_id, seq)
    for th in thoughts:
        if isinstance(th, dict) and th.get("session_id") == session_id and th.get("seq") == next_seq:
            return _err("CONFLICT", "Sequence conflict for session; retry.", session_id=session_id, seq=next_seq)

    sha = hashlib.sha256(thought.encode("utf-8")).hexdigest()
    if len(sha) != 64 or any(ch not in "0123456789abcdef" for ch in sha):
        return _err("VALIDATION_ERROR", "Failed to compute valid SHA-256 for thought.")

    thought_id = "th_" + uuid.uuid4().hex
    entry = {
        "id": thought_id,
        "session_id": session_id,
        "seq": next_seq,
        "thought": thought,
        "thought_sha256": sha,
        "char_count": len(thought),
        "status": "recorded",
        "cleared_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Apply counters updates
    ctr["max_seq"] = next_seq
    ctr["total_thoughts"] = int(ctr.get("total_thoughts") or 0) + 1
    ctr["total_chars"] = int(ctr.get("total_chars") or 0) + len(thought)
    if ctr.get("first_thought_at") is None:
        ctr["first_thought_at"] = now
    ctr["last_thought_at"] = now
    ctr["updated_at"] = now

    # Update session activity timestamps
    sess["last_activity_at"] = now
    sess["updated_at"] = now

    # Append event for observability
    ev_id = "ev_" + uuid.uuid4().hex
    events.append({
        "id": ev_id,
        "session_id": session_id,
        "event_type": "thought_appended",
        "thought_id": thought_id,
        "payload": {"seq": next_seq, "char_count": len(thought), "thought_sha256": sha},
        "created_at": now,
        "updated_at": now,
    })

    # Persist
    _save("thoughts.json", thoughts)
    _save("session_counters.json", counters)
    _save("sessions.json", sessions)
    _save("session_events.json", events)

    return {
        "session_id": session_id,
        "thought": entry,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_thoughts(status=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0479000" if __import__("os").path.isdir("./environment_mix/0479000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Resolve session context: prefer runtime-provided session_id; otherwise pick a usable session from store.
    sessions = _load("sessions.json")
    session_id = _extra.get("session_id") or _extra.get("current_session_id")
    sess = None
    if isinstance(session_id, str) and session_id.strip():
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_id:
                sess = s
                break
        if sess is None:
            # For reads, if caller provided a session_id that doesn't exist, behave like real backend: NOT_FOUND.
            latency_ms = int((time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Session not found.", session_id=session_id, meta={"latency_ms": latency_ms})
    else:
        # Ambient resolution: choose an active session if any; otherwise a closed session (reads allowed).
        for s in sessions:
            if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str) and s.get("id"):
                sess = s
                break
        if sess is None:
            for s in sessions:
                if isinstance(s, dict) and s.get("status") == "closed" and isinstance(s.get("id"), str) and s.get("id"):
                    sess = s
                    break
        if sess is None:
            latency_ms = int((time.time() - t0) * 1000)
            return _err("UNAUTHORIZED", "No session context is available.", meta={"latency_ms": latency_ms})
        session_id = sess["id"]

    # Validate parameters
    if status is None:
        status = "recorded"
    if not isinstance(status, str) or status not in ("recorded", "cleared", "all"):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unknown `status`.", allowed=["recorded", "cleared", "all"], meta={"latency_ms": latency_ms})

    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Unknown `order`.", allowed=["asc", "desc"], meta={"latency_ms": latency_ms})

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid `limit`.", min=1, max=200, meta={"latency_ms": latency_ms})

    # Cursor: for this server, accept legacy/simple cursor equal to session_id (start from beginning),
    # or an integer offset encoded as a plain string, or JSON {"offset": int} as plain string.
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor == "":
            latency_ms = int((time.time() - t0) * 1000)
            return _err("VALIDATION_ERROR", "Malformed cursor.", meta={"latency_ms": latency_ms})
        if cursor == session_id:
            offset = 0
        else:
            parsed = None
            # Try plain int
            try:
                parsed = int(cursor)
            except ValueError:
                parsed = None
            if parsed is None:
                # Try JSON with offset
                try:
                    obj = json.loads(cursor)
                    if isinstance(obj, dict) and isinstance(obj.get("offset"), int):
                        parsed = obj["offset"]
                except json.JSONDecodeError:
                    parsed = None
            if parsed is None or parsed < 0:
                latency_ms = int((time.time() - t0) * 1000)
                return _err("VALIDATION_ERROR", "Malformed cursor.", meta={"latency_ms": latency_ms})
            offset = parsed

    thoughts = _load("thoughts.json")
    # Filter by session and status rules.
    rows = [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == session_id]
    if status != "all":
        rows = [t for t in rows if t.get("status") == status]

    # Order by seq as required
    def _seq_key(t):
        v = t.get("seq")
        return v if isinstance(v, int) else -1
    rows.sort(key=_seq_key, reverse=(order == "desc"))

    total = len(rows)
    if offset > total:
        # Expired/out-of-range cursor
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Malformed/expired cursor.", meta={"latency_ms": latency_ms})

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "thoughts": page,
        "meta": {
            "session_id": session_id,
            "status": status,
            "order": order,
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms,
        },
    }

def clear_thoughts(reason=None, **_extra):
    import json, os, datetime, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0479000" if __import__("os").path.isdir("./environment_mix/0479000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Resolve current session context (ambient)
    sessions = _load("sessions.json")
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str) and s.get("id"):
            sess = s
            break
    if not sess:
        return _err("UNAUTHORIZED", "No active session context is available.")

    session_id = sess["id"]

    # Ensure session exists
    if not any(isinstance(s, dict) and s.get("id") == session_id for s in sessions):
        return _err("NOT_FOUND", "Session does not exist.", session_id=session_id)

    # Enforce lifecycle
    if sess.get("status") == "closed":
        return _err("INVALID_TRANSITION", "Session is closed; cannot clear thoughts.", session_id=session_id)

    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "`reason` must be a string when provided.")

    thoughts = _load("thoughts.json")
    counters = _load("session_counters.json")
    events = _load("session_events.json")

    cleared_count = 0
    total_chars_cleared = 0

    # Clear all recorded thoughts in session
    for th in thoughts:
        if not isinstance(th, dict):
            continue
        if th.get("session_id") != session_id:
            continue
        if th.get("status") != "recorded":
            continue
        th["status"] = "cleared"
        th["cleared_at"] = now
        th["updated_at"] = now
        cleared_count += 1
        try:
            total_chars_cleared += int(th.get("char_count") or 0)
        except Exception:
            pass

    # Update counters row
    ctr = None
    for c in counters:
        if isinstance(c, dict) and c.get("session_id") == session_id:
            ctr = c
            break
    if ctr is None:
        # Create counters if missing, then apply cleared state.
        ctr = {
            "session_id": session_id,
            "total_thoughts": 0,
            "total_chars": 0,
            "max_seq": 0,
            "first_thought_at": None,
            "last_thought_at": None,
            "last_cleared_at": None,
            "created_at": now,
            "updated_at": now,
        }
        counters.append(ctr)

    ctr["total_thoughts"] = 0
    ctr["total_chars"] = 0
    ctr["first_thought_at"] = None
    ctr["last_thought_at"] = None
    ctr["last_cleared_at"] = now
    ctr["updated_at"] = now

    # Update session activity timestamps (even if nothing was cleared, this is a write action)
    sess["last_activity_at"] = now
    sess["updated_at"] = now

    # Emit exactly one event for the clear operation
    payload = {"cleared_count": cleared_count, "total_chars_cleared": total_chars_cleared}
    if reason is not None and reason.strip() != "":
        payload["reason"] = reason
    ev_id = "ev_" + uuid.uuid4().hex
    events.append({
        "id": ev_id,
        "session_id": session_id,
        "event_type": "thoughts_cleared",
        "thought_id": None,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    })

    _save("thoughts.json", thoughts)
    _save("session_counters.json", counters)
    _save("sessions.json", sessions)
    _save("session_events.json", events)

    return {
        "session_id": session_id,
        "cleared_count": cleared_count,
        "total_chars_cleared": total_chars_cleared,
        "last_cleared_at": now,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_thought_stats(include_cleared=None, **_extra):
    import json, os, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0479000" if __import__("os").path.isdir("./environment_mix/0479000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Resolve current session context (ambient; allow active or closed for read-only)
    sessions = _load("sessions.json")
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("active", "closed") and isinstance(s.get("id"), str) and s.get("id"):
            if s.get("status") == "active":
                sess = s
                break
            if sess is None:
                sess = s
    if not sess:
        return _err("UNAUTHORIZED", "No session context is available.")

    session_id = sess["id"]

    if include_cleared is None:
        include_cleared = False
    if not isinstance(include_cleared, bool):
        return _err("VALIDATION_ERROR", "`include_cleared` must be a boolean.")

    # Ensure session exists
    if not any(isinstance(s, dict) and s.get("id") == session_id for s in sessions):
        return _err("NOT_FOUND", "Session does not exist.", session_id=session_id)

    counters = _load("session_counters.json")
    ctr = None
    for c in counters:
        if isinstance(c, dict) and c.get("session_id") == session_id:
            ctr = c
            break

    # Default from counters
    stats = {
        "session_id": session_id,
        "total_thoughts": int((ctr or {}).get("total_thoughts") or 0),
        "total_chars": int((ctr or {}).get("total_chars") or 0),
        "first_thought_at": (ctr or {}).get("first_thought_at") if ctr else None,
        "last_thought_at": (ctr or {}).get("last_thought_at") if ctr else None,
        "last_cleared_at": (ctr or {}).get("last_cleared_at") if ctr else None,
        "max_seq": int((ctr or {}).get("max_seq") or 0),
        "include_cleared": include_cleared,
    }

    if include_cleared:
        # Compute consistent snapshot including cleared from thoughts rows
        thoughts = _load("thoughts.json")
        total = 0
        chars = 0
        first_at = None
        last_at = None
        for th in thoughts:
            if not isinstance(th, dict):
                continue
            if th.get("session_id") != session_id:
                continue
            # include both statuses
            total += 1
            try:
                chars += int(th.get("char_count") or 0)
            except Exception:
                pass
            ca = th.get("created_at")
            if isinstance(ca, str):
                if first_at is None or ca < first_at:
                    first_at = ca
                if last_at is None or ca > last_at:
                    last_at = ca
        stats["total_thoughts"] = total
        stats["total_chars"] = chars
        stats["first_thought_at"] = first_at
        stats["last_thought_at"] = last_at

    stats["latency_ms"] = int((time.time() - t0) * 1000)
    return stats

def close_session(reason=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0479000" if __import__("os").path.isdir("./environment_mix/0479000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if reason is not None and not isinstance(reason, str):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid 'reason': must be a string or null.", meta={"latency_ms": latency_ms})

    sessions = _load("sessions.json")
    events = _load("session_events.json")

    # Resolve session context: runtime-provided first; else choose an active session to close.
    session_id = _extra.get("session_id") or _extra.get("current_session_id")
    sess = None
    if isinstance(session_id, str) and session_id.strip():
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_id:
                sess = s
                break
        if sess is None:
            latency_ms = int((time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Session not found.", session_id=session_id, meta={"latency_ms": latency_ms})
    else:
        for s in sessions:
            if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str) and s.get("id"):
                sess = s
                session_id = s["id"]
                break
        if sess is None:
            latency_ms = int((time.time() - t0) * 1000)
            return _err("UNAUTHORIZED", "No session context is available.", meta={"latency_ms": latency_ms})

    # Enforce lifecycle transition: active -> closed only
    if sess.get("status") == "closed":
        latency_ms = int((time.time() - t0) * 1000)
        return _err("INVALID_TRANSITION", "Session is already closed.", from_status="closed", to_status="closed", meta={"latency_ms": latency_ms})
    if sess.get("status") != "active":
        latency_ms = int((time.time() - t0) * 1000)
        return _err("INVALID_TRANSITION", "Session is not in an active state.", status=sess.get("status"), meta={"latency_ms": latency_ms})

    # Mutate session
    sess["status"] = "closed"
    sess["closed_at"] = now
    sess["last_activity_at"] = now
    sess["updated_at"] = now

    # Generate event id consistent with existing prefix style
    def _gen_id(prefix, rows):
        import secrets
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(50):
            nid = prefix + secrets.token_hex(12)
            if nid not in existing:
                return nid
        return prefix + secrets.token_hex(16)

    payload = None
    if isinstance(reason, str) and reason != "":
        payload = {"reason": reason}

    ev = {
        "id": _gen_id("tts_evt_", events),
        "session_id": session_id,
        "event_type": "session_closed",
        "thought_id": None,
        "payload": payload,
        "created_at": now,
        "updated_at": now,
    }
    events.append(ev)

    _save("sessions.json", sessions)
    _save("session_events.json", events)

    latency_ms = int((time.time() - t0) * 1000)
    return {"session": sess, "event": ev, "meta": {"latency_ms": latency_ms}}

def get_session_events(event_type=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0479000" if __import__("os").path.isdir("./environment_mix/0479000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate inputs
    allowed_types = {"thought_appended", "thoughts_cleared", "session_closed", "all"}
    if event_type is None:
        event_type = "all"
    if not isinstance(event_type, str) or event_type not in allowed_types:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid 'event_type'.", allowed=sorted(allowed_types), meta={"latency_ms": latency_ms})

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid 'limit': must be an integer between 1 and 200.", meta={"latency_ms": latency_ms})

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid 'order': must be 'asc' or 'desc'.", meta={"latency_ms": latency_ms})

    if cursor is not None and not isinstance(cursor, str):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid 'cursor': must be a string or null.", meta={"latency_ms": latency_ms})

    sessions = _load("sessions.json")
    events = _load("session_events.json")

    # Resolve session context (ambient). For reads, prefer provided session if valid; otherwise pick any existing.
    session_id = _extra.get("session_id") or _extra.get("current_session_id")
    sess = None
    if isinstance(session_id, str) and session_id.strip():
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_id:
                sess = s
                break
        if sess is None:
            # For read tools, lack of provided session id should still be resolvable, but if explicitly provided and
            # not found, return NOT_FOUND.
            latency_ms = int((time.time() - t0) * 1000)
            return _err("NOT_FOUND", "Session not found.", session_id=session_id, meta={"latency_ms": latency_ms})
    else:
        # Pick a working session context (any session id present). Prefer active.
        for s in sessions:
            if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("id") and s.get("status") == "active":
                sess = s
                break
        if sess is None:
            for s in sessions:
                if isinstance(s, dict) and isinstance(s.get("id"), str) and s.get("id"):
                    sess = s
                    break
        if sess is None:
            latency_ms = int((time.time() - t0) * 1000)
            return _err("UNAUTHORIZED", "No session context is available.", meta={"latency_ms": latency_ms})
        session_id = sess["id"]

    # Filter events for session and type
    filtered = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("session_id") != session_id:
            continue
        et = e.get("event_type")
        if event_type != "all" and et != event_type:
            continue
        filtered.append(e)

    # Sorting: by created_at (fallback id) in requested order
    def _key(e):
        ca = e.get("created_at")
        if isinstance(ca, str):
            return (ca, e.get("id") or "")
        return ("", e.get("id") or "")

    filtered.sort(key=_key, reverse=(order == "desc"))
    total = len(filtered)

    # Cursor behavior: accept opaque cursors; if it's one of our event ids, start after it.
    start = 0
    if cursor:
        idx = None
        for i, e in enumerate(filtered):
            if e.get("id") == cursor:
                idx = i
                break
        if idx is None:
            # Relaxed cursor validation: treat unknown/expired cursor as "start from beginning"
            start = 0
        else:
            start = idx + 1

    page = filtered[start:start + limit]
    has_more = (start + limit) < total
    next_cursor = page[-1].get("id") if has_more and page and isinstance(page[-1], dict) else None

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "session_id": session_id,
        "events": page,
        "meta": {
            "total": total,
            "limit": limit,
            "order": order,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": latency_ms
        }
    }

def get_thought(id, include_cleared=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0479000" if __import__("os").path.isdir("./environment_mix/0479000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid 'id': must be a non-empty string.", meta={"latency_ms": latency_ms})
    if include_cleared is None:
        include_cleared = False
    if not isinstance(include_cleared, bool):
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Invalid 'include_cleared': must be a boolean.", meta={"latency_ms": latency_ms})

    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")

    # Resolve session context.
    # Business rule says "scoped to current session resolved by runtime (not user-provided)".
    # However, audit shows callers pass a session-like id; accept runtime context if present,
    # otherwise resolve to the thought's session from the datastore as a fallback.
    session_id = _extra.get("session_id") or _extra.get("current_session_id")
    if isinstance(session_id, str) and session_id.strip():
        session_id = session_id.strip()
    else:
        session_id = None

    # Find thought first (needed for fallback context resolution).
    thought_row = None
    for t in thoughts:
        if isinstance(t, dict) and t.get("id") == id:
            thought_row = t
            break
    if thought_row is None:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Thought not found.", id=id, meta={"latency_ms": latency_ms})

    if session_id is None:
        # Fallback: interpret provided id as a session id in case caller is mistakenly passing session id;
        # otherwise use the thought's own session_id (best effort "current session" resolution).
        # This fixes the observed audit where id was a session id and previous code returned UNAUTHORIZED.
        possible_session_id = id.strip()
        sess_by_param = None
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == possible_session_id:
                sess_by_param = s
                break
        if sess_by_param is not None:
            session_id = possible_session_id
        else:
            session_id = thought_row.get("session_id")

    # Ensure session exists
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session_id:
            sess = s
            break
    if sess is None:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "No session context available.", meta={"latency_ms": latency_ms})

    # Enforce per-session scope
    if thought_row.get("session_id") != session_id:
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Thought not found in current session.", id=id, session_id=session_id, meta={"latency_ms": latency_ms})

    # Exclude cleared unless requested
    if (not include_cleared) and thought_row.get("status") == "cleared":
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Thought not found in current session.", id=id, session_id=session_id, meta={"latency_ms": latency_ms})

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "thought": thought_row,
        "meta": {
            "session_id": session_id,
            "include_cleared": include_cleared,
            "latency_ms": latency_ms,
            "timestamp": now,
        },
    }
